'use strict';
// Hidden acceptance tests for p14: every expected value comes from an independent Python implementation of README.md.
const test = require('node:test');
const assert = require('node:assert/strict');
const { cycleStarts, cycleBounds, prorate, invoice } = require('../src');

test("cycleStarts: anchor 31 does not drift through short months", () => {
  assert.deepStrictEqual(cycleStarts(31, "2025-01-31", 8), ["2025-01-31", "2025-02-28", "2025-03-31", "2025-04-30", "2025-05-31", "2025-06-30", "2025-07-31", "2025-08-31"]);
});

test("cycleStarts: anchor 30 in February", () => {
  assert.deepStrictEqual(cycleStarts(30, "2025-01-30", 5), ["2025-01-30", "2025-02-28", "2025-03-30", "2025-04-30", "2025-05-30"]);
});

test("cycleStarts: anchor 29 from a leap day", () => {
  assert.deepStrictEqual(cycleStarts(29, "2024-02-29", 6), ["2024-02-29", "2024-03-29", "2024-04-29", "2024-05-29", "2024-06-29", "2024-07-29"]);
});

test("cycleStarts: anchor 29 reaches a leap February", () => {
  assert.deepStrictEqual(cycleStarts(29, "2023-12-29", 4), ["2023-12-29", "2024-01-29", "2024-02-29", "2024-03-29"]);
});

test("cycleStarts: anchor 31 across the leap February of 2024", () => {
  assert.deepStrictEqual(cycleStarts(31, "2023-12-31", 5), ["2023-12-31", "2024-01-31", "2024-02-29", "2024-03-31", "2024-04-30"]);
});

test("cycleStarts: anchor 31 across February 2000 (century leap year)", () => {
  assert.deepStrictEqual(cycleStarts(31, "2000-01-31", 3), ["2000-01-31", "2000-02-29", "2000-03-31"]);
});

test("cycleStarts: anchor 31 across February 2100 (century, not leap)", () => {
  assert.deepStrictEqual(cycleStarts(31, "2100-01-31", 3), ["2100-01-31", "2100-02-28", "2100-03-31"]);
});

test("cycleStarts: anchor 31 across February 1900 (century, not leap)", () => {
  assert.deepStrictEqual(cycleStarts(31, "1900-01-31", 3), ["1900-01-31", "1900-02-28", "1900-03-31"]);
});

test("cycleStarts: year boundary", () => {
  assert.deepStrictEqual(cycleStarts(15, "2024-11-15", 4), ["2024-11-15", "2024-12-15", "2025-01-15", "2025-02-15"]);
});

test("cycleStarts: first start in a short month", () => {
  assert.deepStrictEqual(cycleStarts(31, "2025-02-28", 4), ["2025-02-28", "2025-03-31", "2025-04-30", "2025-05-31"]);
});

test("cycleStarts: two years of anchor 31", () => {
  assert.deepStrictEqual(cycleStarts(31, "2025-01-31", 24), ["2025-01-31", "2025-02-28", "2025-03-31", "2025-04-30", "2025-05-31", "2025-06-30", "2025-07-31", "2025-08-31", "2025-09-30", "2025-10-31", "2025-11-30", "2025-12-31", "2026-01-31", "2026-02-28", "2026-03-31", "2026-04-30", "2026-05-31", "2026-06-30", "2026-07-31", "2026-08-31", "2026-09-30", "2026-10-31", "2026-11-30", "2026-12-31"]);
});

test("cycleStarts: anchor 29 over four years", () => {
  assert.deepStrictEqual(cycleStarts(29, "2024-02-29", 49), ["2024-02-29", "2024-03-29", "2024-04-29", "2024-05-29", "2024-06-29", "2024-07-29", "2024-08-29", "2024-09-29", "2024-10-29", "2024-11-29", "2024-12-29", "2025-01-29", "2025-02-28", "2025-03-29", "2025-04-29", "2025-05-29", "2025-06-29", "2025-07-29", "2025-08-29", "2025-09-29", "2025-10-29", "2025-11-29", "2025-12-29", "2026-01-29", "2026-02-28", "2026-03-29", "2026-04-29", "2026-05-29", "2026-06-29", "2026-07-29", "2026-08-29", "2026-09-29", "2026-10-29", "2026-11-29", "2026-12-29", "2027-01-29", "2027-02-28", "2027-03-29", "2027-04-29", "2027-05-29", "2027-06-29", "2027-07-29", "2027-08-29", "2027-09-29", "2027-10-29", "2027-11-29", "2027-12-29", "2028-01-29", "2028-02-29"]);
});

test("cycleStarts: count 1 and count 0", () => {
  assert.deepStrictEqual(cycleStarts(31, '2025-01-31', 1), ['2025-01-31']);
  assert.deepStrictEqual(cycleStarts(31, '2025-01-31', 0), []);
});

test("cycleBounds: anchor 31, mid March", () => {
  assert.deepStrictEqual(cycleBounds(31, "2025-03-15"), {"start": "2025-02-28", "next": "2025-03-31", "days": 31});
});

test("cycleBounds: anchor 31, on a long-month start", () => {
  assert.deepStrictEqual(cycleBounds(31, "2025-03-31"), {"start": "2025-03-31", "next": "2025-04-30", "days": 30});
});

test("cycleBounds: anchor 31, the clamped February start itself", () => {
  assert.deepStrictEqual(cycleBounds(31, "2025-02-28"), {"start": "2025-02-28", "next": "2025-03-31", "days": 31});
});

test("cycleBounds: anchor 31, leap day", () => {
  assert.deepStrictEqual(cycleBounds(31, "2024-02-29"), {"start": "2024-02-29", "next": "2024-03-31", "days": 31});
});

test("cycleBounds: anchor 31, mid February of a leap year (29-day cycle)", () => {
  assert.deepStrictEqual(cycleBounds(31, "2024-02-15"), {"start": "2024-01-31", "next": "2024-02-29", "days": 29});
});

test("cycleBounds: anchor 1, leap February", () => {
  assert.deepStrictEqual(cycleBounds(1, "2024-02-29"), {"start": "2024-02-01", "next": "2024-03-01", "days": 29});
});

test("cycleBounds: anchor 1, February 2000 has 29 days", () => {
  assert.deepStrictEqual(cycleBounds(1, "2000-02-29"), {"start": "2000-02-01", "next": "2000-03-01", "days": 29});
});

test("cycleBounds: anchor 1, February 2100 has 28 days", () => {
  assert.deepStrictEqual(cycleBounds(1, "2100-02-28"), {"start": "2100-02-01", "next": "2100-03-01", "days": 28});
});

test("cycleBounds: anchor 1, February 1900 has 28 days", () => {
  assert.deepStrictEqual(cycleBounds(1, "1900-02-28"), {"start": "1900-02-01", "next": "1900-03-01", "days": 28});
});

test("cycleBounds: anchor 15 across the year boundary", () => {
  assert.deepStrictEqual(cycleBounds(15, "2025-01-10"), {"start": "2024-12-15", "next": "2025-01-15", "days": 31});
});

test("cycleBounds: anchor 15 on its own start", () => {
  assert.deepStrictEqual(cycleBounds(15, "2025-01-15"), {"start": "2025-01-15", "next": "2025-02-15", "days": 31});
});

test("cycleBounds: anchor 30 in February", () => {
  assert.deepStrictEqual(cycleBounds(30, "2025-02-28"), {"start": "2025-02-28", "next": "2025-03-30", "days": 30});
});

test("cycleBounds: anchor 29 the day after a clamped start", () => {
  assert.deepStrictEqual(cycleBounds(29, "2025-03-01"), {"start": "2025-02-28", "next": "2025-03-29", "days": 29});
});

test("cycleBounds: anchor 31 on January 1", () => {
  assert.deepStrictEqual(cycleBounds(31, "2025-01-01"), {"start": "2024-12-31", "next": "2025-01-31", "days": 31});
});

