test("prorate: 31-day cycle rounds half up past .5", () => {
  assert.strictEqual(prorate(1000, 2500, "2025-01-10", {"start": "2025-01-01", "next": "2025-02-01", "days": 31}), 1065);
});

test("prorate: 31-day cycle below .5", () => {
  assert.strictEqual(prorate(1000, 2500, "2025-01-11", {"start": "2025-01-01", "next": "2025-02-01", "days": 31}), 1016);
});

test("prorate: exactly half a cent goes up (30-day cycle)", () => {
  assert.strictEqual(prorate(0, 5, "2025-04-28", {"start": "2025-04-01", "next": "2025-05-01", "days": 30}), 1);
});

test("prorate: exactly half a cent goes up (28-day cycle)", () => {
  assert.strictEqual(prorate(1000, 1007, "2025-02-15", {"start": "2025-02-01", "next": "2025-03-01", "days": 28}), 4);
});

test("prorate: 29-day leap cycle divides evenly", () => {
  assert.strictEqual(prorate(1000, 3900, "2024-02-15", {"start": "2024-02-01", "next": "2024-03-01", "days": 29}), 1500);
});

test("prorate: last day of the cycle counts as one remaining day", () => {
  assert.strictEqual(prorate(1000, 4100, "2025-01-31", {"start": "2025-01-01", "next": "2025-02-01", "days": 31}), 100);
});

test("prorate: first day of the cycle charges the full difference", () => {
  assert.strictEqual(prorate(1000, 2500, "2025-01-01", {"start": "2025-01-01", "next": "2025-02-01", "days": 31}), 1500);
});

test("prorate: 0.4 rounds down", () => {
  assert.strictEqual(prorate(100, 104, "2025-04-28", {"start": "2025-04-01", "next": "2025-05-01", "days": 30}), 0);
});

test("prorate: 0.7 rounds up", () => {
  assert.strictEqual(prorate(100, 107, "2025-04-28", {"start": "2025-04-01", "next": "2025-05-01", "days": 30}), 1);
});

test("prorate: large amounts stay exact", () => {
  assert.strictEqual(prorate(5, 123456789, "2025-01-18", {"start": "2025-01-01", "next": "2025-02-01", "days": 31}), 55754677);
});

test("prorate: Feb 28 days: 27 remaining", () => {
  assert.strictEqual(prorate(2000, 5999, "2025-02-02", {"start": "2025-02-01", "next": "2025-03-01", "days": 28}), 3856);
});

test("prorate: a downgrade or an unchanged price charges exactly 0", () => {
  assert.strictEqual(prorate(2500, 1000, '2025-01-10', {"start": "2025-01-01", "next": "2025-02-01", "days": 31}), 0);
  assert.strictEqual(prorate(2500, 2500, '2025-01-10', {"start": "2025-01-01", "next": "2025-02-01", "days": 31}), 0);
  assert.ok(Object.is(prorate(2500, 1000, '2025-01-10', {"start": "2025-01-01", "next": "2025-02-01", "days": 31}), 0));
});

