test("invoice: no changes: a base line per cycle", () => {
  const sub = {"anchorDay": 15, "startedOn": "2025-01-15", "plans": {"basic": 1000, "pro": 2500, "plus": 2500, "team": 6000}, "initialPlan": "basic", "changes": []};
  assert.deepStrictEqual(invoice(sub, "2025-01-15"), {"cycleStart": "2025-01-15", "lines": [{"kind": "base", "plan": "basic", "amountCents": 1000}], "totalCents": 1000});
  assert.deepStrictEqual(invoice(sub, "2025-02-15"), {"cycleStart": "2025-02-15", "lines": [{"kind": "base", "plan": "basic", "amountCents": 1000}], "totalCents": 1000});
  assert.deepStrictEqual(invoice(sub, "2025-03-15"), {"cycleStart": "2025-03-15", "lines": [{"kind": "base", "plan": "basic", "amountCents": 1000}], "totalCents": 1000});
});

